// まだ入っていない曲は、ネットからそのまま流しながら（待たせない）、裏で丸ごと保存する
const MUSIC = 'toh-music-2';
async function ranged(req, box) {
  const c = await caches.open(box || MUSIC), url = req.url.split('#')[0].split('?')[0];
  const full = await c.match(url);
  if (!full) { if (box) { const res = await fetch(url); if (!res.ok) return res; await c.put(url, res); return ranged(req, box); } fetch(url).then(res => { if (res.ok && res.status === 200) c.put(url, res); }).catch(() => {}); return fetch(req); }
  const buf = await full.arrayBuffer(), m = /bytes=(\d+)-(\d*)/.exec(req.headers.get('range') || ''), type = /\.m4a$/.test(url) ? 'audio/mp4' : 'audio/mpeg';
  if (!m) return new Response(buf, { status: 200, headers: { 'Content-Type': type, 'Content-Length': buf.byteLength, 'Accept-Ranges': 'bytes' } });
  const a = +m[1], b = m[2] ? Math.min(+m[2], buf.byteLength - 1) : buf.byteLength - 1;
  return new Response(buf.slice(a, b + 1), { status: 206, headers: { 'Content-Type': type, 'Content-Range': `bytes ${a}-${b}/${buf.byteLength}`, 'Content-Length': b - a + 1, 'Accept-Ranges': 'bytes' } });
}
self.addEventListener('fetch', e => {
  const r = e.request; if (r.method !== 'GET') return;
  if (/\/bgm\/.*\.m4a($|\?)/.test(r.url)) { e.respondWith(ranged(r).catch(() => fetch(r))); return; }
  if (/\.mp3($|\?)/.test(r.url)) { e.respondWith(ranged(r, VER).catch(() => fetch(r))); return; }  // 効果音
  // 本体（html・js）は、ネットがあれば最新を取りにいく（更新がすぐ届く）。なければ保存した物
  if (r.mode === 'navigate' || /\.(js|css|html|webmanifest)($|\?)/.test(r.url)) {
    e.respondWith(fetch(r, { cache: 'no-cache' }).then(res => { if (res.ok) { const cp = res.clone(); caches.open(VER).then(c => c.put(r, cp)); } return res; }).catch(() => caches.match(r, { ignoreSearch: true }).then(h => h || caches.match('./index.html'))));
    return;
  }
  e.respondWith(caches.match(r, { ignoreSearch: true }).then(hit => hit || fetch(r).then(res => { if (res.ok) { const cp = res.clone(); caches.open(VER).then(c => c.put(r, cp)); } return res; }).catch(() => caches.match('./index.html'))));
});
